const fs = require('fs');
const path = require('path');

// ============================================================
// generar_466_manual_y_vacunas.js
// ============================================================
// Tres cosas.
//
// 1. "¿CUAL LE TOCA?" vs "¿CUALES TIENE?"
//    Son preguntas distintas y ahora se responden distinto:
//
//      Tú: ¿qué vacuna le toca?
//      Chiqui: · Antirrábica — en 20 días (12 sep)
//              (tiene 2 más registradas)
//              [¿Qué vacunas tiene puestas?]
//
//      Tú: ¿qué vacunas tiene puestas?
//      Chiqui: · Felocell — en 343 días (1 ago 2027)
//              · Antirrábica — en 20 días (12 sep)
//              · Leucemia — sin próxima fecha anotada
//
//    La primera muestra SOLO la mas urgente: vencida antes que
//    pendiente, y entre pendientes la mas cercana. Igual para
//    antiparasitarios.
//
// 2. EL MANUAL AHORA CUBRE LA APP COMPLETA
//    Antes eran los 15 caminos que Casandra menciono. Ahora son 29:
//    se sumaron revision corporal, frecuencia respiratoria,
//    temperatura, celos, enfermedades, momentos, calendario, analisis,
//    signos de alerta, corregir un registro, archivar una mascota, el
//    boton "Todo normal", cerrar sesion y recuperar contraseña.
//
//    Y las palabras pasaron de FRASES a RAICES: 'present' cubre
//    presentar, presento y presentarlos. Las frases largas fallaban por
//    una palabra en medio — "¿como los presento?" no calzaba con
//    "presentar".
//
// 3. TIP NUEVO: LLEGA OTRA MASCOTA A CASA
//    Nueve consejos que se encadenan: espacios separados, intercambio
//    de olores, recursos dobles, terreno neutral, puerta de por medio
//    para gatos, mantener la calma, atender primero al que ya vivia
//    ahi, no dejarlos solos, y premiar la convivencia.
//
// REQUISITO: script 465 desplegado.
//
// Si algo no calza, ABORTA sin escribir.
// ============================================================

const RUTA = 'components/ChiquiChat.tsx';
const CHAT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico ningun archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const destino = path.join(process.cwd(), RUTA);
if (!fs.existsSync(destino)) abortar('no se encontro ' + RUTA + '.');

const actual = fs.readFileSync(destino, 'utf8');
if (actual.includes('quiereHistorial')) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes('quisisteDecir')) {
  abortar('falta el script 465. Correlo primero.');
}

const comp = Buffer.from(CHAT_B64, 'base64').toString('utf8');

const REQUERIDOS = [
  "'use client'", 'export default function ChiquiChat',
  'quiereHistorial', "tema: 'presentacion'", 'Revisión corporal',
  'Temperatura corporal', 'Momentos', 'quisisteDecir',
];
for (const r of REQUERIDOS) {
  if (!comp.includes(r)) abortar('el contenido nuevo no incluye [' + r + ']. Script corrupto.');
}

// El manual tiene que haber crecido de verdad.
const caminos = comp.split('const COMOLO')[1].split('function buscarComolo')[0].split('palabras: [').length - 1;
if (caminos < 25) {
  abortar('el manual tiene solo ' + caminos + ' caminos. Esperaba al menos 25.');
}
console.log('  OK  el manual cubre ' + caminos + ' caminos');
console.log('  OK  el contenido nuevo esta completo');

fs.writeFileSync(destino, comp, 'utf8');
console.log('');
console.log('OK: ' + RUTA);
console.log('');
console.log('Listo. Prueba con "¿que vacuna le toca?" y con "llega otro perro".');
